package com.pablo.controlgastos;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import java.nio.charset.StandardCharsets;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public final class SecretStore{private static final String A="ControlGastosMail";private SecretStore(){}private static SecretKey key()throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias(A)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(A,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return((KeyStore.SecretKeyEntry)k.getEntry(A,null)).getSecretKey();}public static void put(Context c,String value){try{Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.ENCRYPT_MODE,key());String v=Base64.encodeToString(x.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(x.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);c.getSharedPreferences("card_secret",0).edit().putString("mail",v).apply();}catch(Exception e){throw new RuntimeException(e);}}public static String get(Context c){try{String v=c.getSharedPreferences("card_secret",0).getString("mail","");if(v.isEmpty())return"";String[]q=v.split(":",2);Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(q[0],Base64.NO_WRAP)));return new String(x.doFinal(Base64.decode(q[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}catch(Exception e){return"";}}}